changeSet.sql:
UPDATE parser SET name = 'PEP Belgique – Pouvoirs locaux (50 000 hab. et plus)', description = 'Bourgmestres, gouverneurs de provinces, échevins, présidents de CPAS et députés provinciaux des collectivités de 50 000 habitants ou plus (catégorie BE-AMLR, règlement (UE) 2024/1624 applicable le 10/07/2027)', website_url = 'https://public.regimand.be/', parameters = '{"wikidataEndpoint": "https://query.wikidata.org/sparql", "lblodEndpoint": "https://centrale-vindplaats.lblod.info/sparql", "regimandUrl": "https://public.regimand.be", "regimandDelayMs": "500", "minPopulation": "50000", "countryQid": "Q31"}', licence = 'CC0 1.0 (Wikidata), Licence Ouverte Flandre (LBLOD Mandatendatabank) et données publiques de la Cour des comptes (Regimand)', attribution = 'Wikidata (Q31) ; Agentschap Binnenlands Bestuur (LBLOD Mandatendatabank) ; Cour des comptes, public.regimand.be', notes = 'Bourgmestres et gouverneurs : Wikidata et LBLOD. Échevins, présidents de CPAS et députés provinciaux : déclarations de mandats de la Cour des comptes (Regimand), interrogées collectivité par collectivité (environ 3 minutes pour 40 collectivités). Regimand publie le dernier exercice clos (2024 en novembre 2026) : un mandat sans date de fin dans ce dernier exercice est repris comme en cours. Pour couvrir toutes les communes, mettre minPopulation à 0 (environ 580 communes, plus d’une demi-heure). Une collectivité dont la lecture Regimand échoue est citée dans le message d’exécution ; si toutes échouent, l’exécution s’arrête.' WHERE dataset_name = 'be_pep_local_executives';
INSERT INTO pep_function (category_id, label, institution, expected_holders) SELECT c.id, 'Échevin, président de CPAS ou député provincial d''une collectivité de 50 000 habitants ou plus', 'Pouvoirs locaux', NULL FROM pep_category c WHERE c.code = 'BE-AMLR' AND NOT EXISTS (SELECT 1 FROM pep_function f WHERE f.category_id = c.id AND f.label LIKE 'Échevin, président de CPAS ou député provincial%');
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Échevins, présidents de CPAS et députés provinciaux des communes et provinces de 50 000 habitants ou plus (Wallonie, Bruxelles et Flandre), d’après les déclarations de mandats de la Cour des comptes (Regimand) ; mandats terminés repris pendant la durée de rétention.', 'Regimand publie le dernier exercice clos, avec un décalage : un changement d’échevin intervenu depuis n’est pas encore visible. Les communes de moins de 50 000 habitants ne sont lues que si minPopulation est abaissé.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BE-AMLR' AND f.label LIKE 'Échevin, président de CPAS ou député provincial%' AND p.dataset_name = 'be_pep_local_executives' AND NOT EXISTS (SELECT 1 FROM pep_function_parser x WHERE x.function_id = f.id AND x.parser_id = p.id);
